import{_ as r,c as t,o as a,a2 as i}from"./chunks/framework.mqLGQ42V.js";const h=JSON.parse('{"title":"介绍 (Introduction) - Rive 入门指南","description":"欢迎来到 Rive 文档。我们将文档分成了以下几个子章节。如果你找不到所需的信息或对我们有任何疑问，请加入我们的 Twitter、Discord，或通过 填写此表单 与我们联系。 Rive 新手？这里有一些入门建议：","frontmatter":{"title":"介绍 (Introduction) - Rive 入门指南","description":"欢迎来到 Rive 文档。我们将文档分成了以下几个子章节。如果你找不到所需的信息或对我们有任何疑问，请加入我们的 Twitter、Discord，或通过 填写此表单 与我们联系。 Rive 新手？这里有一些入门建议：","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 入门指南, 介绍"}]]},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1774867914000}'),n={name:"guide/introduction.md"};function o(l,e,c,s,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<p>入门</p><h1 id="介绍-introduction" tabindex="-1">介绍 (Introduction) <a class="header-anchor" href="#介绍-introduction" aria-label="Permalink to &quot;介绍 (Introduction)&quot;">​</a></h1><p>欢迎来到 Rive 文档。我们将文档分成了以下几个子章节。如果你找不到所需的信息或对我们有任何疑问，请加入我们的 <a href="https://twitter.com/rive_app" target="_blank" rel="noreferrer">Twitter</a>、<a href="https://discord.com/invite/FGjmaTr" target="_blank" rel="noreferrer">Discord</a>，或通过 <a href="https://rive.app/contact" target="_blank" rel="noreferrer">填写此表单</a> 与我们联系。</p><h2 id="​-入门-getting-started" tabindex="-1"><a href="#getting-started">​</a> 入门 (Getting Started) <a class="header-anchor" href="#​-入门-getting-started" aria-label="Permalink to &quot;[​](#getting-started) 入门 (Getting Started)&quot;">​</a></h2><p>Rive 新手？这里有一些入门建议：</p><ul><li>立即 <a href="https://rive.app/login/?redirect=https%3A%2F%2Feditor.rive.app" target="_blank" rel="noreferrer">创建账号</a> 并尝试 Rive 编辑器。</li><li>准备好开始设计和制作动画了吗？查阅这里的 Rive 文档，或者观看 <a href="https://youtube.com/playlist?list=PLujDTZWVDSsFGonP9kzAnvryowW098-p3" target="_blank" rel="noreferrer">Rive 101</a> 系列短视频教程。</li><li>想直接在你的应用和游戏中使用 Rive？查看 <a href="/docs/runtimes/getting-started">应用运行时 (App Runtimes) 文档</a> 和 <a href="/docs/games/unreal">游戏运行时 (Game Runtimes) 文档</a> 获取快速上手指南、示例和代码片段。</li><li>对使用 Rive 的场景感到好奇？我们在 <a href="https://rive.app/use-cases" target="_blank" rel="noreferrer">使用场景页面</a> 提供了示例、博客、教程等内容。</li></ul><h2 id="​-探索-rive" tabindex="-1"><a href="#explore-rive">​</a> 探索 Rive <a class="header-anchor" href="#​-探索-rive" aria-label="Permalink to &quot;[​](#explore-rive) 探索 Rive&quot;">​</a></h2><h2 id="界面概览-interface-overview" tabindex="-1">界面概览 (Interface Overview) <a class="header-anchor" href="#界面概览-interface-overview" aria-label="Permalink to &quot;界面概览 (Interface Overview)&quot;">​</a></h2><p><a href="/docs/editor/interface-overview/overview">准备好开始在 Rive 中进行设计和制作动画了吗？编辑器是你创建、制作动画并利用强大的状态机 (State Machine) 构建逻辑（控制不同动画如何混合）的地方。从那里，你可以导出作品，并通过我们的运行时 (Runtimes) 之一将其放入你的应用或游戏中。</a>[## 应用运行时 (App Runtimes)</p><p><a href="/docs/runtimes/getting-started">应用运行时是开源库，能够在各种平台和框架（包括 Web、iOS、Android、Flutter、React Native 等）上实时渲染和更新你的 Rive 文件。</a>[## 游戏运行时 (Game Runtimes)</p><p><a href="/docs/games/unreal">游戏运行时是开源库，允许在 Unity、Unreal 和 Defold 中实时渲染和更新你的 Rive 文件，并且易于集成到自定义引擎中。</a></p><h2 id="市场概览-marketplace-overview" tabindex="-1">市场概览 (Marketplace Overview) <a class="header-anchor" href="#市场概览-marketplace-overview" aria-label="Permalink to &quot;市场概览 (Marketplace Overview)&quot;">​</a></h2><p><a href="/docs/community/marketplace-overview">在 Rive 市场分享和重新创作作品。</a>[## 管理 (Admin)</p><p><a href="https://help.rive.app/account-admin/account-overview/account-overview" target="_blank" rel="noreferrer">管理账号、团队和方案所需的所有信息。</a>[## 服务条款 (Terms of Service)</p><p><a href="https://help.rive.app/legal/terms-of-service" target="_blank" rel="noreferrer">我们所有的法律文件，如服务条款、可接受使用政策和隐私政策。</a></p>',15)])])}const u=r(n,[["render",o]]);export{h as __pageData,u as default};
